// Defining custom validator rules as an AST grammar parser
enum ValRule {
    MinLength(usize),
    Alphanumeric,
}

struct FieldValidator {
    rules: Vec<ValRule>,
}

impl FieldValidator {
    fn validate(&self, value: &str) -> bool {
        for rule in &self.rules {
            match rule {
                ValRule::MinLength(len) => if value.len() < *len { return false; },
                ValRule::Alphanumeric => if !value.chars().all(|c| c.is_alphanumeric()) { return false; },
            }
        }
        true
    }
}
