// Straightforward statically compiled validation rules
fn validate_input(value: &str) -> Result<(), &'static str> {
    if value.len() < 5 {
        return Err("Input must be at least 5 characters long");
    }
    if !value.chars().all(|c| c.is_alphanumeric()) {
        return Err("Input must be alphanumeric");
    }
    Ok(())
}
